    @classmethod
    def _convert_inline_system_message(
        cls,
        msg,
        openai_messages: list[dict[str, Any]],
    ) -> None:
        """Convert an inline ``role: system`` message at its original position.

        The message is emitted as an OpenAI ``system`` message at the point
        where it appears in the conversation, rather than being merged with
        the top-level system prompt. This preserves the conversation
        structure so that the prefix stays stable for KV-cache reuse.

        For list content, Claude Code's ``x-anthropic-billing-header`` text
        blocks are stripped (they carry a per-request hash that would defeat
        prefix caching) and the remaining text blocks are concatenated into a
        single string. If nothing remains after stripping, the message is
        dropped entirely.
        """
        if isinstance(msg.content, str):
            openai_messages.append({"role": "system", "content": msg.content})
            return

        system_parts: list[str] = []
        for block in msg.content:
            if block.type == "text" and block.text:
                if block.text.startswith("x-anthropic-billing-header"):
                    continue
                system_parts.append(block.text)

        if system_parts:
            openai_messages.append(
                {"role": "system", "content": "".join(system_parts)}
            )

